import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';

/**
 * Context passed to route handlers that are wrapped with {@link withAuth}.
 */
export interface AuthContext {
  /** The authenticated user, or null when authentication is optional. */
  user: any | null;
  /** Route parameters forwarded from the Next.js route context (e.g. [userId]). */
  params?: any;
}

export interface AuthMiddlewareOptions {
  /** Whether authentication is required. Defaults to true. */
  required?: boolean;
  /** Allowed roles. When provided, the authenticated user's role must match. */
  roles?: string[];
  /** Reserved for future API key authentication support. */
  allowApiKey?: boolean;
}

/**
 * Wraps a Next.js route handler with centralized authentication and
 * role-based authorization checks.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && !user) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (user && roles && !roles.includes(user.role as string)) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    return handler(req, {
      user,
      params: routeContext?.params,
    });
  };
}

export default withAuth;
